dding: 2rem 0;\n  border-top: 1px solid #e9ecef;\n  text-align: center;\n}\n\n.footer-content[_ngcontent-%COMP%] {\n  display: flex;\n  flex-direction: column;\n  gap: 0.5rem;\n}\n\n.credits[_ngcontent-%COMP%] {\n  color: #6c757d;\n  font-size: 0.9rem;\n  margin: 0;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: 0.75rem;\n}\n\n.credits[_ngcontent-%COMP%]   a[_ngcontent-%COMP%] {\n  color: #495057;\n  text-decoration: none;\n  transition: color 0.2s;\n}\n\n.credits[_ngcontent-%COMP%]   a[_ngcontent-%COMP%]:hover {\n  color: #2c3e50;\n}\n\n.license[_ngcontent-%COMP%] {\n  color: #868e96;\n  font-size: 0.8rem;\n  margin: 0;\n}\n\n.license[_ngcontent-%COMP%]   a[_ngcontent-%COMP%] {\n  color: inherit;\n  text-decoration: none;\n}\n\n.license[_ngcontent-%COMP%]   a[_ngcontent-%COMP%]:hover {\n  text-decoration: underline;\n}\n\n@media (max-width: 768px) {\n  .container[_ngcontent-%COMP%] {\n    padding: 1rem;\n  }\n  .surah-grid[_ngcontent-%COMP%], .juz-grid[_ngcontent-%COMP%] {\n    grid-template-columns: 1fr;\n  }\n  .header[_ngcontent-%COMP%]   h1[_ngcontent-%COMP%] {\n    font-size: 2rem;\n  }\n  .navigation-tabs[_ngcontent-%COMP%] {\n    width: 100%;\n  }\n  .nav-tab[_ngcontent-%COMP%] {\n    flex: 1;\n    padding: 0.75rem;\n  }\n  .search-input[_ngcontent-%COMP%] {\n    max-width: none;\n  }\n}\n/*# sourceMappingURL=data:application/json;charset=utf-8;base64, */"]
